struct ListNode {
    int val; ListNode* next = nullptr;
    ListNode(int v) : val(v) {}
};

ListNode* build(vector<int>& vals) {
    ListNode dummy(0), *cur = &dummy;    // 哨兵 + 尾插
    for (int v : vals) { cur->next = new ListNode(v); cur = cur->next; }
    return dummy.next;
}

class Solution {
public:
    ListNode* reverseList(ListNode* head) { return head; }
};

int main() {
    int n;
    cin >> n;
    vector<int> vals(n);
