    for (ListNode* p = Solution().reverseList(build(vals)); p; p = p->next)
        cout << p->val << " ";           // 链表一律 dump 成空格分隔的一行
    cout << "\n";
    return 0;
}

1|二叉树:
#include <bits/stdc++.h>
using namespace std;

struct TreeNode {
    int val; TreeNode *left = nullptr, *right = nullptr;
    TreeNode(int v) : val(v) {}
};

TreeNode* build(vector<string>& t) {
    if (t.empty() || t[0] == "null") return nullptr;
    TreeNode* root = new TreeNode(stoi(t[0]));
    queue<TreeNode*> q;
    q.push(root);
    for (int i = 1; i < (int)t.size() && !q.empty(); i++) {
        TreeNode* cur = q.front(); q.pop();
        if (t[i] != "null") { cur->left = new TreeNode(stoi(t[i])); q.push(cur->left); }
        if (++i < (int)t.size() && t[i] != "null") { cur->right = new TreeNode(stoi(t[i])); q.push(cur->right); }
    }
    return root;
}

class Solution {
public:
    int maxDepth(TreeNode* root) { return 0; }
};

int main() {
    int n; cin >> n;
    vector<string> t(n);
    for (string& s : t) cin >> s;        // 第一行是 n，后面是层序值
    cout << Solution().maxDepth(build(t)) << "\n";
}

1|图论:
#include <bits/stdc++.h>
using namespace std;

int main() {
    int n, m;
    cin >> n >> m;
    vector<vector<int>> g(n + 1);        // 1-indexed
    for (int i = 0; i < m; i++) {
        int u, v;
        cin >> u >> v;
        g[u].push_back(v);
        g[v].push_back(u);               // 无向图才加这一行
    }

    vector<bool> seen(n + 1, false);
    int cnt = 0;
    for (int s = 1; s <= n; s++) {
        if (seen[s]) continue;
        cnt++;
        queue<int> q;
        q.push(s); seen[s] = true;
        while (!q.empty()) {
            int u = q.front(); q.pop();
            for (int v : g[u])
                if (!seen[v]) { seen[v] = true; q.push(v); }
        }
    }
    cout << cnt << "\n";
    return 0;
}

