struct TreeNode {
    int val; TreeNode *left = nullptr, *right = nullptr;
    TreeNode(int v) : val(v) {}
};

TreeNode* build(vector<string>& t) {
    if (t.empty() || t[0] == "null") return nullptr;
    TreeNode* root = new TreeNode(stoi(t[0]));
    queue<TreeNode*> q;
    q.push(root);
    for (int i = 1; i < (int)t.size() && !q.empty(); i++) {
        TreeNode* cur = q.front(); q.pop();
        if (t[i] != "null") { cur->left = new TreeNode(stoi(t[i])); q.push(cur->left); }
        if (++i < (int)t.size() && t[i] != "null") { cur->right = new TreeNode(stoi(t[i])); q.push(cur->right); }
    }
    return root;
}

