2|动态规划:
#include <bits/stdc++.h>
using namespace std;

int main() {
    int n, bag;
    cin >> n >> bag;
    vector<int> weight(n), value(n);
    for (int i = 0; i < n; i++) cin >> weight[i];
    for (int i = 0; i < n; i++) cin >> value[i];

    vector<int> dp(bag + 1, 0);
    for (int i = 0; i < n; i++)
        for (int j = bag; j >= weight[i]; j--)   // 01 背包倒序；完全背包正序
            dp[j] = max(dp[j], dp[j - weight[i]] + value[i]);
    cout << dp[bag] << "\n";
    return 0;
}

2|图论:
#include <bits/stdc++.h>
using namespace std;

int parent[100005];

int find(int x) {
    while (parent[x] != x) {
        parent[x] = parent[parent[x]];   // 路径压缩
        x = parent[x];
    }
    return x;
}

int main() {
    int n, m;
    cin >> n >> m;
    for (int i = 1; i <= n; i++) parent[i] = i;
    for (int i = 0; i < m; i++) {
        int u, v;
        cin >> u >> v;
        int ru = find(u), rv = find(v);
        if (ru == rv) {                  // 冗余连接：这条边让图成环
            cout << u << " " << v << "\n";
            return 0;
        }
        parent[ru] = rv;
    }
    return 0;
}
